import React, { useState } from "react";

export default function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState("");

  const [filters, setFilters] = useState({
    publications: true,
    trials: true,
    risk: true
  });

  const toggleFilter = (key) => {
    setFilters((prev) => ({
      ...prev,
      [key]: !prev[key]
    }));
  };

  const handleRun = async () => {
    setLoading(true);

    setStep("🔍 Fetching research...");
    setTimeout(() => setStep("📊 Ranking publications..."), 800);
    setTimeout(() => setStep("🤖 Generating AI summary..."), 1200);

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          disease,
          intent,
          location
        })
      });

      const result = await res.json();
      setData(result);
    } catch (err) {
      alert("❌ Backend not connected");
    }

    setLoading(false);
    setStep("");
  };

  const safeData = data || {
    publications: [],
    clinical_trials: []
  };

  const riskScore = Math.min(90, safeData.publications.length * 10);

  return (
    <div style={container}>

      {/* LEFT PANEL */}
      <div style={leftPanel}>
        <h2 style={{ marginBottom: "20px" }}>Curalink X</h2>

        <input
          placeholder="Filter by disease"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
          style={input}
        />

        <h3 style={{ marginTop: "20px" }}>Stats</h3>
        <p>📄 Papers: {safeData.publications.length}</p>
        <p>🧪 Trials: {safeData.clinical_trials.length}</p>

        <h3 style={{ marginTop: "20px" }}>Insight Filters</h3>

        <label style={filterItem}>
          <input
            type="checkbox"
            checked={filters.publications}
            onChange={() => toggleFilter("publications")}
          />
          Publications
        </label>

        <label style={filterItem}>
          <input
            type="checkbox"
            checked={filters.trials}
            onChange={() => toggleFilter("trials")}
          />
          Clinical Trials
        </label>

        <label style={filterItem}>
          <input
            type="checkbox"
            checked={filters.risk}
            onChange={() => toggleFilter("risk")}
          />
          Risk Analysis
        </label>
      </div>

      {/* CENTER PANEL */}
      <div style={centerPanel}>
        <h1>🧠 AI Medical Research Copilot</h1>
        <p style={{ opacity: 0.7 }}>
          Turn complex medical queries into structured insights
        </p>

        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
          style={textarea}
        />

        <button onClick={handleRun} style={button}>
          {loading ? "Running..." : "Send message"}
        </button>

        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          style={input}
        />

        {loading && <p>⏳ {step}</p>}
      </div>

      {/* RIGHT PANEL */}
      <div style={rightPanel}>

        {/* SUMMARY */}
        <div style={card}>
          <h3>Dynamic Insights</h3>
          {!data && <p>No data yet</p>}
          {data && <p>{data.summary}</p>}
        </div>

        {/* ANALYTICS */}
        {filters.publications && (
          <div style={card}>
            <h3>📊 Research Analytics</h3>

            <p>Papers: {safeData.publications.length}</p>
            <div style={progressBar}>
              <div
                style={{
                  ...progressFill,
                  width: `${safeData.publications.length * 10}%`
                }}
              />
            </div>

            <p style={{ marginTop: "10px" }}>
              Trials: {safeData.clinical_trials.length}
            </p>
            <div style={progressBar}>
              <div
                style={{
                  ...progressFill,
                  width: `${safeData.clinical_trials.length * 15}%`
                }}
              />
            </div>
          </div>
        )}

        {/* RISK */}
        {filters.risk && (
          <div style={card}>
            <h3>⚠️ Risk Confidence</h3>
            <p>{riskScore}%</p>
          </div>
        )}

        {/* PAPERS */}
        {filters.publications && (
          <div style={card}>
            <h3>Research Papers</h3>

            {safeData.publications.map((p, i) => (
              <div key={i} style={item}>
                <strong>{p.title}</strong>
                <p style={meta}>
                  {p.source} • {p.year}
                </p>
              </div>
            ))}
          </div>
        )}

        {/* TRIALS */}
        {filters.trials && (
          <div style={card}>
            <h3>Clinical Trials</h3>

            {safeData.clinical_trials.map((t, i) => (
              <div key={i} style={item}>
                <strong>{t.title}</strong>
                <p style={meta}>Status: {t.status}</p>
              </div>
            ))}
          </div>
        )}

      </div>
    </div>
  );
}

/* 🎨 STYLES */

const container = {
  display: "flex",
  height: "100vh",
  background: "linear-gradient(135deg,#0f172a,#020617)",
  color: "white"
};

const leftPanel = {
  width: "260px",
  padding: "20px",
  background: "#1e293b"
};

const centerPanel = {
  flex: 1,
  padding: "20px"
};

const rightPanel = {
  width: "380px",
  padding: "20px",
  background: "#1e293b",
  overflowY: "auto"
};

const input = {
  width: "100%",
  padding: "10px",
  marginTop: "10px",
  borderRadius: "8px",
  border: "none"
};

const textarea = {
  width: "100%",
  height: "120px",
  marginTop: "10px",
  padding: "10px",
  borderRadius: "10px"
};

const button = {
  marginTop: "10px",
  padding: "12px",
  width: "100%",
  background: "linear-gradient(90deg,#3b82f6,#8b5cf6)",
  border: "none",
  borderRadius: "10px",
  color: "white",
  fontWeight: "bold",
  cursor: "pointer"
};

const card = {
  background: "#0f172a",
  padding: "15px",
  marginTop: "15px",
  borderRadius: "10px"
};

const item = {
  marginTop: "10px"
};

const meta = {
  fontSize: "12px",
  opacity: 0.7
};

const filterItem = {
  display: "flex",
  gap: "10px",
  marginTop: "8px"
};

const progressBar = {
  width: "100%",
  height: "10px",
  background: "#334155",
  borderRadius: "10px",
  overflow: "hidden"
};

const progressFill = {
  height: "100%",
  background: "linear-gradient(90deg,#3b82f6,#8b5cf6)"
};
